package com.medibook.service;
import com.medibook.dto.AppointmentDtos.*; import com.medibook.entity.*; import com.medibook.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import org.springframework.http.HttpStatus; import java.time.*; import java.util.*;
@Service public class AppointmentService {
 private final AppointmentRepository appointments;private final DoctorProfileRepository doctors;private final AvailabilityRepository availability;private final NotificationRepository notifications;private final UserRepository users;private final DoctorService doctorService;private final EmailNotifier email;private final long cancellationHours;private final ZoneId zone;
 public AppointmentService(AppointmentRepository a,DoctorProfileRepository d,AvailabilityRepository av,NotificationRepository n,UserRepository u,DoctorService ds,EmailNotifier email,@Value("${medibook.cancellation-hours:24}") long hours,@Value("${medibook.timezone:Asia/Kolkata}") String tz){appointments=a;doctors=d;availability=av;notifications=n;users=u;doctorService=ds;this.email=email;cancellationHours=hours;zone=ZoneId.of(tz);}
 @Transactional public Appointment book(long patientId,Booking in){DoctorProfile doctor=doctors.lockById(in.doctorId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Doctor not found"));if(!doctor.isVerified()||!doctor.getUser().isActive())throw new ResponseStatusException(HttpStatus.CONFLICT,"Doctor is not accepting bookings");Instant end=validateSlot(in.doctorId(),in.startAt());if(!appointments.findConflicts(in.doctorId(),in.startAt(),end).isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"That appointment slot is no longer available");Appointment a=appointments.save(new Appointment(patientId,in.doctorId(),in.startAt(),end,doctor.isManualConfirmation()?AppointmentStatus.PENDING:AppointmentStatus.CONFIRMED,in.reason()));String status=a.getStatus().name().toLowerCase();notifications.save(new Notification(patientId,"Appointment booked","Your appointment request with Dr. "+doctor.getUser().getFullName()+" is "+status+"."));notifications.save(new Notification(in.doctorId(),"New appointment","You have a new appointment request."));users.findById(patientId).ifPresent(u->email.send(u.getEmail(),"MediBook appointment booked","Your appointment with Dr. "+doctor.getUser().getFullName()+" is "+status+"."));email.send(doctor.getUser().getEmail(),"MediBook appointment request","You have a new appointment request.");return a;}
 @Transactional public Appointment cancel(long id,long actor){Appointment a=owned(id,actor);if(a.getStatus()!=AppointmentStatus.PENDING&&a.getStatus()!=AppointmentStatus.CONFIRMED)throw conflict("Only pending or confirmed appointments can be cancelled");if(a.getStartAt().isBefore(Instant.now().plus(Duration.ofHours(cancellationHours))))throw conflict("Appointments can only be cancelled at least "+cancellationHours+" hours ahead");a.setStatus(AppointmentStatus.CANCELLED);notifyPair(a,"Appointment cancelled","An appointment was cancelled.");return a;}
 @Transactional public Appointment reschedule(long id,long actor,Reschedule in){Appointment old=owned(id,actor);if(old.getStatus()!=AppointmentStatus.PENDING&&old.getStatus()!=AppointmentStatus.CONFIRMED)throw conflict("This appointment cannot be rescheduled");if(old.getStartAt().isBefore(Instant.now().plus(Duration.ofHours(cancellationHours))))throw conflict("Appointment is inside the cancellation window");Instant minimumStart=Instant.now().plus(Duration.ofHours(cancellationHours));if(in.startAt().isBefore(minimumStart))throw conflict("New appointment must be at least "+cancellationHours+" hours ahead");doctors.lockById(old.getDoctorId()).orElseThrow();Instant end=validateSlot(old.getDoctorId(),in.startAt());if(!appointments.findConflicts(old.getDoctorId(),in.startAt(),end).stream().filter(x->!x.getId().equals(old.getId())).toList().isEmpty())throw conflict("That appointment slot is no longer available");old.setStartAt(in.startAt());old.setEndAt(end);notifyPair(old,"Appointment rescheduled","Your appointment time has changed.");return old;}
 @Transactional public Appointment changeStatus(long id,long doctorId,String value){Appointment a=appointments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));if(!a.getDoctorId().equals(doctorId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You do not manage this appointment");AppointmentStatus next;try{next=AppointmentStatus.valueOf(value.toUpperCase());}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status");}boolean ok=switch(a.getStatus()){case PENDING->next==AppointmentStatus.CONFIRMED||next==AppointmentStatus.REJECTED||next==AppointmentStatus.CANCELLED;case CONFIRMED->next==AppointmentStatus.COMPLETED||next==AppointmentStatus.CANCELLED;default->false;};if(!ok)throw conflict("Invalid appointment status transition");a.setStatus(next);notifyPair(a,"Appointment "+next.name().toLowerCase(),"Your appointment status is now "+next.name().toLowerCase()+".");return a;}
 @Transactional public Appointment adminCancel(long id){Appointment a=appointments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));if(a.getStatus()!=AppointmentStatus.PENDING&&a.getStatus()!=AppointmentStatus.CONFIRMED)throw conflict("Only active appointments can be cancelled");a.setStatus(AppointmentStatus.CANCELLED);notifyPair(a,"Appointment cancelled","An administrator cancelled this appointment.");return a;}
 public List<Appointment> mine(long id,String role){return role.equals("ROLE_DOCTOR")?appointments.findByDoctorIdOrderByStartAtAsc(id):appointments.findByPatientIdOrderByStartAtDesc(id);}
 public Appointment get(long id,long actor,String role){Appointment a=appointments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));if(!role.equals("ROLE_ADMIN")&&!a.getPatientId().equals(actor)&&!a.getDoctorId().equals(actor))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You cannot access this appointment");return a;}
 private Appointment owned(long id,long actor){Appointment a=appointments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));if(!a.getPatientId().equals(actor))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the booking patient can change this appointment");return a;}
 private Instant validateSlot(long doctor,Instant start){if(!start.isAfter(Instant.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Appointment must be in the future");ZonedDateTime local=start.atZone(zone);for(var s:availability.findByDoctorIdAndDayOfWeek(doctor,local.getDayOfWeek())){LocalTime t=s.getStartTime();while(!t.plusMinutes(s.getSlotMinutes()).isAfter(s.getEndTime())){Instant candidate=local.toLocalDate().atTime(t).atZone(zone).toInstant();LocalTime end=t.plusMinutes(s.getSlotMinutes());boolean breakConflict=s.getBreakStart()!=null&&t.isBefore(s.getBreakEnd())&&end.isAfter(s.getBreakStart());if(candidate.equals(start)&&!breakConflict)return start.plus(Duration.ofMinutes(s.getSlotMinutes()));t=end;}}throw new ResponseStatusException(HttpStatus.CONFLICT,"Selected time is outside doctor availability");}
 private void notifyPair(Appointment a,String title,String msg){notifications.save(new Notification(a.getPatientId(),title,msg));notifications.save(new Notification(a.getDoctorId(),title,msg));users.findById(a.getPatientId()).ifPresent(u->email.send(u.getEmail(),"MediBook: "+title,msg));users.findById(a.getDoctorId()).ifPresent(u->email.send(u.getEmail(),"MediBook: "+title,msg));}private ResponseStatusException conflict(String s){return new ResponseStatusException(HttpStatus.CONFLICT,s);}
}
